#!/usr/bin/env node
/* Writes public/_redirects:
 *   1. SEO locale 301s (battle slugs + versus cross-locale, from matchups.json)
 *   2. EN slug + DE name aliases → /:lang/pokemon/:id/
 *   3. sitemap.xml / robots.txt 200 passthrough
 *   4. SPA fallback
 * Keep pokemon helper logic in sync with src/lib/pokemon-slug-redirects.ts
 * (covered by vitest). Do not edit public/_redirects by hand. */
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const pokemon = JSON.parse(readFileSync(path.join(root, 'src/data/i18n/de/pokemon.json'), 'utf8'));
const matchupsJson = JSON.parse(readFileSync(path.join(root, 'src/data/matchups.json'), 'utf8'));

function slugifyDeName(name) {
  return name
    .toLowerCase()
    .replace(/ä/g, 'ae')
    .replace(/ö/g, 'oe')
    .replace(/ü/g, 'ue')
    .replace(/ß/g, 'ss')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

const LANGS = ['de', 'en'];
const lines = [
  '# Generated by scripts/generate-pokemon-redirects.mjs — do not edit by hand.',
  '',
  '# SEO locale 301s — one battle slug and one versus slug per locale.',
  '# Trailing-slash destinations match the rest of the site (Pretty URLs).',
  '/en/kampf-simulator  /en/battle-simulator/  301',
  '/de/battle-simulator  /de/kampf-simulator/  301',
  '',
  '# Unprefixed team hub — Language-302 (same idea as `/` in netlify.toml).',
  '# Must sit before the SPA splat; `_redirects` can win over netlify.toml.',
  '/team   /de/team/  302  Language=de',
  '/team   /en/team/  302',
  '/team/  /de/team/  302  Language=de',
  '/team/  /en/team/  302',
];

for (const m of matchupsJson.matchups) {
  lines.push(`/en/versus/${m.slugDe}  /en/versus/${m.slugEn}/  301`);
  lines.push(`/de/versus/${m.slugEn}  /de/versus/${m.slugDe}/  301`);
}

lines.push('');
lines.push('# Pokémon slug aliases → numeric canonical (trailing slash).');

const seen = new Set();

for (const [id, row] of Object.entries(pokemon)) {
  const aliases = new Set();
  if (row.slug) aliases.add(row.slug);
  if (row.name) aliases.add(slugifyDeName(row.name));
  for (const alias of aliases) {
    if (!alias || alias === id) continue;
    for (const lang of LANGS) {
      const from = `/${lang}/pokemon/${alias}`;
      if (seen.has(from)) continue;
      seen.add(from);
      lines.push(`${from}  /${lang}/pokemon/${id}/  301`);
    }
  }
}

lines.push('');
lines.push('# Static files — never let the SPA catch-all serve HTML for these.');
lines.push('/sitemap.xml  /sitemap.xml  200');
lines.push('/robots.txt   /robots.txt   200');
lines.push('');
lines.push('# Netlify SPA fallback — every other route serves index.html (client-side router)');
lines.push('/*    /index.html   200');
lines.push('');

writeFileSync(path.join(root, 'public/_redirects'), `${lines.join('\n')}\n`);
const versusRules = matchupsJson.matchups.length * 2;
console.log(
  `[redirects] 2 battle + ${versusRules} versus + ${seen.size} pokemon slug rules → public/_redirects`,
);
